function markdownToHtml(md) {
  if (!md) return '';

  let html = md
    // Escape basic HTML entities
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')

    // Headers
    .replace(/^### (.*$)/gim, '<h3>$1</h3>')
    .replace(/^## (.*$)/gim, '<h2>$1</h2>')
    .replace(/^# (.*$)/gim, '<h1>$1</h1>')

    // Bold and Italic
    .replace(/\*\*\*(.*?)\*\*\*/g, '<strong><em>$1</em></strong>')
    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.*?)\*/g, '<em>$1</em>')
    .replace(/___(.*?)___/g, '<strong><em>$1</em></strong>')
    .replace(/__(.*?)__/g, '<strong>$1</strong>')
    .replace(/_(.*?)_/g, '<em>$1</em>')

    // Blockquotes
    .replace(/^\> (.*$)/gim, '<blockquote>$1</blockquote>')

    // Inline Code
    .replace(/`([^`]+)`/g, '<code>$1</code>')

    // Unordered Lists
    .replace(/^\s*[\-\*]\s+(.*$)/gim, '<ul><li>$1</li></ul>')

    // Ordered Lists
    .replace(/^\s*\d+\.\s+(.*$)/gim, '<ol><li>$1</li></ol>')

    // Fix adjacent list tags
    .replace(/<\/ul>\s*<ul>/g, '')
    .replace(/<\/ol>\s*<ol>/g, '')

    // Links
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>')

    // Paragraphs (lines with text not inside tags)
    .replace(/^(?!<h|<ul|<ol|<blockquote|<code|<li)(.+)$/gim, '<p>$1</p>');

  return html.trim();
}

const rawMarkdown = $input.first().json.output.body || "";
const htmlContent = markdownToHtml(rawMarkdown);

const styledHtml = `
<!DOCTYPE html>
<html>
<head>
  <style>
    body { font-family: 'Arial', sans-serif; font-size: 11pt; line-height: 1.5; color: #333; }
    h1 { font-size: 20pt; color: #1155cc; margin-top: 18pt; margin-bottom: 6pt; }
    h2 { font-size: 16pt; color: #434343; margin-top: 14pt; margin-bottom: 4pt; }
    h3 { font-size: 13pt; color: #666666; margin-top: 12pt; margin-bottom: 4pt; }
    p { margin-bottom: 8pt; }
    ul, ol { margin-top: 0; margin-bottom: 8pt; padding-left: 20pt; }
    li { margin-bottom: 4pt; }
    blockquote { border-left: 3px solid #ccc; padding-left: 10px; color: #555; font-style: italic; }
    code { font-family: 'Courier New', monospace; background-color: #f4f4f4; padding: 2px 4px; }
  </style>
</head>
<body>
  ${htmlContent}
</body>
</html>
`;

return {
  html: styledHtml,
  documentTitle: $input.first().json.output.request || "Imported Document"
};

const htmlContent = $json.html || "<h1>No Content</h1>";

// Extract title safely using pure JavaScript
const rawTitle = $json.data?.title || ($json.data?.request ? $json.data.request.substring(6) : null);
const docTitle = rawTitle || "Imported Document";

return [{
  json: {
    documentTitle: docTitle
  },
  binary: {
    data: {
      data: Buffer.from(htmlContent, 'utf-8').toString('base64'),
      mimeType: 'text/html',
      fileName: `${docTitle}.html`
    }
  }
}];
